    public static function addLIGHT_TRAVEL_DISTANCE_MPC(FlatBufferBuilder $builder, $LIGHT_TRAVEL_DISTANCE_MPC)
    {
        $builder->addDoubleX(36, $LIGHT_TRAVEL_DISTANCE_MPC, NAN);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param StringOffset
     * @return void
     */
    public static function addCOSMOLOGY_ID(FlatBufferBuilder $builder, $COSMOLOGY_ID)
    {
        $builder->addOffsetX(37, $COSMOLOGY_ID, 0);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endGLX(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // ID
        return $o;
    }

    public static function finishGLXBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, '$GLX');
    }
}
